      "time": "8月12日 19:12",
      "speaker": "",
      "text": "列車の窓に、澄の顔が薄く映っていた。\n\n外の景色を見ようとすると自分の目が重なり、画面を見ようとすると夕日が反射する。澄はノートパソコンの角度を二度変え、結局ふたを閉じた。",
