      "speaker": "澄（内心）",
      "text": "作品を傷つけた過去があるわけではない。\n\nただ、早く正解を出そうとしていたら、誰かが残した時間を消していたかもしれない。その可能性だけが、判断の前でいつも足を止める。",
      "next": "p05",
