      "type": "text",
      "bg": "train",
      "speaker": "澄（内心）",
      "text": "〈まだ列車。着いたら送る〉\n\n送信してから、到着前なのだから正確ではないと思う。けれど、家族への連絡まで報告書のようにしなくていい。今日は、その程度のことから始める。",
