      "type": "text",
      "bg": "breakRoom",
      "speaker": "",
      "text": "「コピーでもあります。でも、描き直した時の判断も入っています。違いを誤差として消すと、描き直した理由まで消えます」\n\nクレールは「面倒」と言う前に、もう一度三枚を見た。",
