      "bg": "equipment",
      "speaker": "クレール",
      "text": "「記録へ残す。二・〇を切ったら止める」\n\nマルクは了承した。澄の違和感は消えないが、警報値ではない。責任者はマルクで、自分は到着したばかりだ。",
