      "type": "text",
      "bg": "equipment",
      "speaker": "澄",
      "text": "「下がり方を確認してからの方が安全です」\n\nマルクは可視光の負荷と照明時間を説明する。クレールが折衷案を出す。\n\n「二・〇を切ったら止める。今の判断も記録に残す」",
