      "type": "text",
      "bg": "scan",
      "speaker": "",
      "text": "白い走査光は、絵を照らすというより薄く剥がしているように見えた。表面の艶、乾燥亀裂、筆の盛り上がりが順番に現れ、肉眼で一枚だった画面が複数の時間へ分かれる。",
