      "type": "text",
      "bg": "scan",
      "speaker": "クレール",
      "text": "「三脚目、鍵穴、肖像、窓。四つとも同じ時期かもしれない」\n\n「可能性はあります」\n\nレオンがすぐに尋ねる。\n\n「ゴッホ本人の変更も？」",
