      "text": "非常停止はすぐには反応しない。画面に「管理者遅延設定：180秒」。\n\nクレールの顔から、冗談が消える。\n\n「誰が遅延を入れた？」\n\nマルクは「誤作動対策です。説明は後で」と答える。",
