      "text": "彼は椅子を一枚分ずらし、元の脚位置へ鉛筆で短い線を引く。\n\n「言葉より、物を動かした跡の方が残る」\n\nその時点で彼は、反復を信じてはいない。ただ検証できる形を作っている。",
