      "type": "text",
      "bg": "bedroomWorld",
      "speaker": "",
      "text": "窓の外が、音もなく白く光る。壁から紫色の粉が落ち、右側から下地の白へ変わっていく。\n\n左の扉が開く。その先には、黄色い廊下。",
