      "bg": "bedroomWorld",
      "speaker": "フィンセント",
      "text": "「待て。そこから先は、まだ描いていない」\n\n澄には廊下が見える。だが床板は二枚分だけで、その先は遠近線と茶色い色面しかない。影もない。",
