      "type": "evidenceText",
      "bg": "bedroomWorld",
      "speaker": "澄",
      "text": "死の直前に見た扉の裏。そこには「M.D.V. 1948」とあった。今の部屋で証拠にするには、扉を安全に回転させ、現物を見なければならない。",
      "evidence": "mdv_signature",
