      "speaker": "澄（内心）",
      "text": "扉の裏を確かめるには、開いた先へ踏み込む必要はない。蝶番側を支え、部屋の内側から回転させればよい。\n\n死の記憶は答えではなく、安全に見る方法を考えるための案内になる。",
