      "type": "text",
      "bg": "bedroomWorld",
      "speaker": "",
      "text": "椅子を鉛筆線へ戻す。左扉を完全に閉じる。ベッドを壁から床板一枚分だけ離す。\n\n白い光が来る。今回は、物の輪郭が崩れない。",
