      "speaker": "フィンセント",
      "text": "「君は前にも、この部屋を動かしたな」\n\n澄は答えようとする。声は出るが、消えた周回の説明にはならない。\n\nフィンセントは首を振る。\n\n「言わなくていい。線が残っている」",
