      "emotion": "業務的な声",
      "text": "クレールは折り畳み椅子へ澄を座らせ、脈拍計を指へ挟む。\n\n「吐き気」\n「ありません」\n「頭痛」\n「少し」\n「名前」\n「水瀬澄」\n「ここは」\n「南仏絵画保存研究所、第三調査室」",
