      "type": "text",
      "bg": "recovery",
      "speaker": "クレール",
      "text": "「手を開いて。次は握って」\n\n澄が従うと、クレールは左右の力を比べ、瞳孔灯を消した。質問の形を崩さないことで、自分の焦りを隠している。",
