      "time": "0:41",
      "speaker": "クレール",
      "text": "「あなたがいなかった十四分、私は何をしてたと思う？」\n\n「非常停止を確認して、私を呼んだ」\n\nクレールの指が、水のボトルの蓋で止まる。\n\n「見てたみたいに言うね」",
