      "type": "text",
      "bg": "breakRoom",
      "speaker": "クレール",
      "text": "「質問を変える。次に変なことをする前に、私の方を見て」\n\n「止めるためですか」\n\n「一人で決めた顔をしてるか確認するため」\n\n彼女は異常を信じたわけではない。澄が、分からない危険を一人で引き受けることを警戒している。",
