      "time": "1888年10月23日 16:40",
      "speaker": "",
      "text": "床へ落ちず、今度は両足で立っていた。\n\n窓の光は前より低い。壁には黄色と青の二点、床には椅子脚の鉛筆線が残っている。安全索だった黒い線は、腰から床へ垂れていた。",
