      "speaker": "フィンセント",
      "text": "「十五秒ではなかったな」\n\n「向こうでは、そのくらいにする予定でした」\n\n「予定は外れた」\n\nフィンセントは黒い線を床から拾う。指でつまんだ瞬間、それは平たい線ではなく、短い木炭の糸になる。",
