      "bg": "saintRemy",
      "speaker": "フィンセント",
      "text": "「外へ出たいのか」\n\n「この層で、どこまで行けるか確認しています」\n\n「なら、自由の話に変えるな。今日は門の外へ行っていない。それだけだ」",
