      "bg": "martaWorkshop",
      "speaker": "マルタ",
      "text": "「比較用の再構成。呼び方が必要なら」\n\nゴッホの真筆でも、真筆を装う模写でもない。三版の差異を一画面で確かめるための道具だった。",
