      "type": "text",
      "bg": "equipment",
      "speaker": "クレール",
      "text": "「冷却第二系統。温度の上がり方が変」\n\n第1故障を止めても残る別系統の過熱。予測線は3時18分から急に上がり、3時31分へ赤い警告を置いている。",
