      "type": "text",
      "speaker": "クレール",
      "text": "「防煙マスクを」\n\n「保管庫側です。取りに行けば二分」\n\n温度曲線は、二分後に停止可能域を外れる。澄は前室の扉を二十センチだけ開ける。",
      "next": "a525x2",
