      "type": "text",
      "speaker": "",
      "text": "中へ入ったのは四十二秒。炎はない。分電盤下部の絶縁材だけが黒く、細い煙を出している。\n\n澄は回路表示を読み、携帯端末へ入力する。喉の奥に、甘い苦味が残った。",
