      "speaker": "クレール",
      "text": "前室を出ると、クレールが澄の肩を掴む。\n\n「咳は？」\n\n「一度だけ」\n\n「めまい」\n\n「ありません」\n\n答えは事実だった。症状がまだ出ていないだけだった。",
