      "type": "text",
      "bg": "loadingBay",
      "speaker": "",
      "text": "キャリーケースの車輪が石の継ぎ目へ落ちる。前と同じ小さな音。\n\n澄は反射的に足を止める。急いで持ち上げるのではなく、一度取っ手を置き、肩の力を抜いた。",
