      "type": "evidenceText",
      "bg": "corridor",
      "speaker": "",
      "text": "澄は手帳の新しいページを四列に分ける。\n\n残像。現在にある物証。立会人。取得する時刻。\n\n記憶そのものを報告書へ入れる欄は作らない。",
      "next": "a604x1",
