      "type": "text",
      "bg": "corridor",
      "speaker": "",
      "text": "最初に作品ではなく、非常口へ向かう。扉の下へ転がる車輪止めを棚へ戻し、砂を掃き、開閉を二度確認する。\n\n初回の死では、正しい出口が小さな物で使えなくなった。",
      "next": "a604x2",
      "visualState": "safety",
