      "type": "text",
      "bg": "corridor",
      "speaker": "澄",
      "text": "「避難経路の写真を、時刻入りで四枚撮ってください」\n\n「撮影担当だけど、避難経路の？」\n\n「今夜の作業記録に必要です」",
