      "speaker": "澄",
      "text": "本当は、ここで一度扉が開かなかった、と続けようとした。\n\n舌の位置が変わる。\n\n「車輪止めが扉へ入る可能性があります」\n\n消えた出来事は、今ここにある危険へ言い換えられた。",
