      "type": "text",
      "bg": "fireControl",
      "speaker": "",
      "text": "3時15分00秒。マルクが主電源を切る。\n\n大きな音はしない。モニターが一枚ずつ暗くなり、冷却ポンプの回転が低くなる。",
